WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_c_circle'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '环形追及', 'kp-trv-c-circle', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "环形追及"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "在环形跑道上，同向奔跑追上一次，就是快者比慢者多跑了一整圈！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“400米环形操场上，甲乙同地同向起跑，甲速度8m/s，乙速度5m/s，多久甲第一次套圈追上乙？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这实际上是异地追及的变形，只不过起始的“拉开距离”变成了一整圈的长度。"}]}, {"type": "katexBlock", "attrs": {"content": "N \\times S_{一圈长度} = (V_{快} - V_{慢}) \\times T \\quad \\text{(N为追上的次数)}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[识别是环形同向跑] --> B[提取跑道周长作为 追及距离 S]\nB --> C[计算速度差 V差]\nC --> D[第一次套圈时间 T = S跑道 ÷ V差]\nD --> E[如果要算第 N 次套圈, 时间就直接乘以 N]"}}]}$$ AS jsonb), NULL, '环形追及的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "环形追及"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_c_circle", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
